<div class="page-heading"><div><div class="eyebrow">WORKSPACE RECORDS</div><h1>Publishing History</h1><p>Review saved drafts and the record of publishing activity.</p></div></div><div class="alert phase-alert">Phase 1 stores drafts only. No announcements have been sent to WordPress by this application.</div><div class="surface table-responsive"><table class="table"><thead><tr><th>Announcement</th><th>Module</th><th>Created by</th><th>Status</th><th>Created (UTC)</th></tr></thead><tbody><?php foreach($rows as $a): ?><tr><td><strong><?= e($a['title']) ?></strong><?php if($a['body']): ?><details class="mt-2"><summary>Read announcement</summary><p class="preserve-lines mt-3"><?= e($a['body']) ?></p></details><?php endif; ?><?php if($a['image_path']): ?><details class="mt-2"><summary>View poster</summary><img class="history-poster" src="<?= e(url('/image?id='.$a['id'])) ?>" alt="<?= e($a['title']) ?>" loading="lazy"></details><?php endif; ?></td><td><?= $a['type']==='partial'?'Partial update':'Scheduled interruption' ?></td><td><?= e($a['author']) ?></td><td><span class="status-badge"><?= e(ucfirst($a['status'])) ?></span></td><td><?= e($a['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5"><div class="empty-state"><h3>No announcements yet</h3><p>Save an announcement draft to start your history.</p></div></td></tr><?php endif; ?></tbody></table></div><h2 class="mt-4 mb-3">Publishing events</h2><div class="surface table-responsive"><table class="table"><thead><tr><th>Announcement</th><th>Status</th><th>Publisher</th><th>Time (UTC)</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?= e($h['title']) ?></td><td><?= e($h['status']) ?></td><td><?= e($h['author']) ?></td><td><?= e($h['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$history): ?><tr><td colspan="4" class="text-secondary p-4">No publishing events recorded.</td></tr><?php endif; ?></tbody></table></div>
